// Small procedural soundscape: no audio downloads or persistent microphone access.
export function createSound({world}){
 let ctx,master,effectsBus,musicBus,music,waterFilter,splashGain,splashEnvelope=0,lastSplash=0,lastSoundTime=0,engine,engineGain,harmonic,harmonicGain,roadGain,windGain,waterGain,hornGain,horn,skidGain,squeal,squealGain,muted=false,volume=.85,musicVolume=.4,musicMuted=false;
 try{const saved=JSON.parse(localStorage.getItem('wainui-audio')||'{}');if(Number.isFinite(saved.effects))volume=Math.max(0,Math.min(1,saved.effects));if(Number.isFinite(saved.music))musicVolume=Math.max(0,Math.min(1,saved.music));muted=saved.muted===true;musicMuted=saved.musicMuted===true}catch{}
 function save(){try{localStorage.setItem('wainui-audio',JSON.stringify({effects:volume,music:musicVolume,muted,musicMuted}))}catch{}}
 const $=s=>document.querySelector(s);const Audio=globalThis.AudioContext||globalThis.webkitAudioContext;
 function gain(value=0){const g=ctx.createGain();g.gain.value=value;g.connect(effectsBus);return g}
 function noise(filterType,frequency){const buffer=ctx.createBuffer(1,ctx.sampleRate*2,ctx.sampleRate),data=buffer.getChannelData(0);let prev=0;for(let i=0;i<data.length;i++){prev=(prev+(Math.random()*2-1)*.06)/1.02;data[i]=prev}const source=ctx.createBufferSource();let peak=.001;for(const v of data)peak=Math.max(peak,Math.abs(v));for(let i=0;i<data.length;i++)data[i]*=.7/peak;source.buffer=buffer;source.loop=true;const filter=ctx.createBiquadFilter();filter.type=filterType;filter.frequency.value=frequency;const out=gain();source.connect(filter);filter.connect(out);source.start();return out}
 function start(){if(!Audio)return;try{if(!ctx){ctx=new Audio();master=ctx.createGain();master.gain.value=0;waterFilter=ctx.createBiquadFilter();waterFilter.type='lowpass';waterFilter.frequency.value=20000;effectsBus=ctx.createGain();effectsBus.gain.value=volume;effectsBus.connect(waterFilter);waterFilter.connect(master);musicBus=ctx.createGain();musicBus.gain.value=musicVolume;musicBus.connect(master);music=createMusic(ctx,musicBus);if(ctx.createDynamicsCompressor){const limiter=ctx.createDynamicsCompressor();limiter.threshold.value=-12;limiter.knee.value=12;limiter.ratio.value=4;limiter.attack.value=.006;limiter.release.value=.2;master.connect(limiter);limiter.connect(ctx.destination)}else master.connect(ctx.destination);engine=ctx.createOscillator();engine.type='triangle';engineGain=gain();engine.connect(engineGain);engine.start();harmonic=ctx.createOscillator();harmonic.type='sawtooth';harmonicGain=gain();const filter=ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=350;harmonic.connect(filter);filter.connect(harmonicGain);harmonic.start();roadGain=noise('lowpass',900);windGain=noise('lowpass',450);waterGain=noise('bandpass',1400);splashGain=noise('bandpass',850);skidGain=noise('bandpass',2300);squeal=ctx.createOscillator();squeal.type='triangle';squeal.frequency.value=820;squealGain=gain();squeal.connect(squealGain);squeal.start();horn=ctx.createOscillator();horn.type='sine';horn.frequency.value=330;hornGain=gain();horn.connect(hornGain);horn.start()}ctx.resume().catch(()=>{})}catch{}}
 function level(node,value){node?.gain.setTargetAtTime(value,ctx.currentTime,.09)}
 // Thunder: brown noise with slow random swells. Close strikes add a sharp crack and keep their highs; distant ones
 // arrive later as a soft, low rumble.
 let lastThunder=0;
 function thunder({delay,distance,power}){const near=1-Math.min(1,distance/2600),length=3.5+Math.min(4,distance/1600),rate=ctx.sampleRate,buffer=ctx.createBuffer(1,Math.floor(rate*length),rate),data=buffer.getChannelData(0);let prev=0,swell=.6,target=1,peak=.001;
  for(let i=0;i<data.length;i++){const t=i/rate;if(i%Math.floor(rate*.11)===0)target=.25+Math.random()*1.1;swell+=(target-swell)*.0005;prev=(prev+(Math.random()*2-1)*.1)/1.012;const attack=Math.min(1,t/(.015+(1-near)*.45)),decay=Math.exp(-t*4/length);data[i]=prev*swell*attack*decay+near*Math.exp(-t*7)*(Math.random()*2-1)*.35;peak=Math.max(peak,Math.abs(data[i]))}
  for(let i=0;i<data.length;i++)data[i]/=peak;const source=ctx.createBufferSource();source.buffer=buffer;const filter=ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=160+near*1900;const out=gain(Math.min(.9,power*(.3+.7*near)));source.connect(filter);filter.connect(out);source.onended=()=>{out.disconnect();filter.disconnect()};source.start(ctx.currentTime+Math.min(delay,25))}
 function update({active,position,vehicle,keys,weather}){if(!ctx)return;level(master,active&&!document.hidden&&!muted?.9:0);level(effectsBus,volume);level(musicBus,musicMuted?0:musicVolume*(keys.h?.55:1));music.update(active&&!document.hidden&&!muted&&!musicMuted&&musicVolume>0);const speed=vehicle?.speed||0,train=vehicle?.kind==='train',throttle=!!keys.w||!!keys.arrowup;engine.frequency.setTargetAtTime(train?55+speed*3:vehicle?.rpm?Math.max(25,vehicle.rpm/120*(vehicle.cylinders||4)):35+speed*4,ctx.currentTime,.12);harmonic.frequency.setTargetAtTime(engine.frequency.value*(train?3:2),ctx.currentTime,.12);level(engineGain,vehicle&&!vehicle.flooded?(train?.16:.2):0);level(harmonicGain,vehicle&&!vehicle.flooded?(throttle?.045:.018):0);level(roadGain,vehicle&&!vehicle.inWater?Math.min(.24,speed*.006):0);level(windGain,.04+(weather?.rain||0)*.11+(weather?.storm||0)*.12);if(weather?.thunder&&weather.thunder.id!==lastThunder){lastThunder=weather.thunder.id;if(active&&!muted)thunder(weather.thunder)}waterFilter.frequency.setTargetAtTime(world.water?.underwater?550:20000,ctx.currentTime,.15);const event=world.water?.splashEvent;if(event&&event.serial!==lastSplash){lastSplash=event.serial;splashEnvelope=Math.min(.6,.12+event.power*.025)}const elapsed=Math.min(.1,Math.max(0,ctx.currentTime-lastSoundTime));lastSoundTime=ctx.currentTime;splashEnvelope*=Math.exp(-elapsed*3.5);level(splashGain,splashEnvelope);const hit=world.hydro.channel(position.x,position.z);const near=hit?1:world.hydro.nearChannel(position.x,position.z,35)?.4:0;level(waterGain,near*.2);const skid=vehicle&&!vehicle.inWater?vehicle.skid||0:0;level(skidGain,skid*.16);level(squealGain,skid*.05);squeal.frequency.setTargetAtTime(760+skid*140+Math.sin(ctx.currentTime*23)*25,ctx.currentTime,.03);level(hornGain,vehicle&&keys.h?(train?.3:.24):0);horn.frequency.setTargetAtTime(train?220:330,ctx.currentTime,.1)}
 const musicMute=$('#music-muted'),musicSlider=$('#music-volume');if(musicMute)musicMute.onchange=()=>{musicMuted=musicMute.checked;save();start()};if(musicSlider)musicSlider.oninput=()=>{musicVolume=Number(musicSlider.value);save();start()};
 const mute=$('#sound-muted'),slider=$('#sound-volume');if(mute)mute.onchange=()=>{muted=mute.checked;save();start()};if(slider)slider.oninput=()=>{volume=Number(slider.value);save();start()};if(slider)slider.value=String(volume);if(mute)mute.checked=muted;if(musicSlider)musicSlider.value=String(musicVolume);if(musicMute)musicMute.checked=musicMuted;addEventListener('keydown',e=>{if(e.key.toLowerCase()==='h')e.preventDefault()});addEventListener('blur',()=>{if(ctx)level(master,0)});document.addEventListener('visibilitychange',()=>{if(ctx&&document.hidden)level(master,0)});return{start,update};
}
